adj = [[] for _ in range(n)]

# Read each employee's known languages
for i in range(n):
    parts = list(map(int, input().split()))
    k = parts[0]
    langs = set(parts[1:])

    # Connect to other employees who share a language
    for j in range(n):
        if i != j:
            other_langs = set(map(int, input().split()))
            if other_langs & langs:
                adj[i].append(j)

# Find connected components using DFS
visited = [False] * n
count = 0

for i in range(n):
    if not visited[i]:
        count += 1
        stack = [i]
        visited[i] = True

        while stack:
            node = stack.pop()
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

# Minimum cost is number of components - 1
print(count - 1)
