import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    t = int(next(it))

    for _ in range(t):
        n = int(next(it))
        m = int(next(it))

        matrix = []
        for _ in range(n):
            row = [int(next(it)) for _ in range(m)]
            matrix.append(row)

        found = False
        answer = ""

        # Try all possible cuts k (1 <= k < m)
        for k in range(1, m):
            # Compute min of each row in left part (first k columns)
            min_left = [min(row[:k]) for row in matrix]

            # Compute max of each row in right part (last m-k columns)
            max_right = [max(row[k:]) for row in matrix]

            # Find rows that can be red: min_left[i] > max_right[j] for all j
            red_candidates = []
            for i in range(n):
                can_be_red = True
                for j in range(n):
                    if min_left[i] <= max_right[j]:
                        can_be_red = False
                        break
                if can_be_red:
                    red_candidates.append(i)

            # Find rows that can be blue: max_right[i] > min_left[j] for all j
            blue_candidates = []
            for i in range(n):
                can_be_blue = True
                for j in range(n):
                    if max_right[i] <= min_left[j]:
                        can_be_blue = False
                        break
                if can_be_blue:
                    blue_candidates.append(i)

            # Check if we can color all rows with at least one red and one blue
            if red_candidates and blue_candidates:
                # Try to color all rows
                colored = [None] * n

                # Assign red to all red candidates
                for i in red_candidates:
                    colored[i] = 'R'

                # Assign blue to all blue candidates
                for i in blue_candidates:
                    colored[i] = 'B'

                # Check if all rows are colored
                if all(colored):
                    # Check if at least one red and one blue
                    if 'R' in colored and 'B' in colored:
                        found = True
                        answer = f"YES\n{''.join(colored)} {k}\n"
                        break

        if found:
            sys.stdout.write(answer)
        else:
            sys.stdout.write("NO\n")

if __name__ == "__main__":
    solve()
"}

