import sys
from collections import defaultdict, deque

def build_tree(n, edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)
    return tree

def get_subtree_representation(node, parent, tree):
    # Get representation of subtree rooted at 'node'
    children = []
    for neighbor in tree[node]:
        if neighbor != parent:
            children.append(get_subtree_representation(neighbor, node, tree))
    # Sort children representations to ensure isomorphic subtrees have same representation
    children.sort()
    return tuple(children)

def count_similar_subtrees(n, edges):
    tree = build_tree(n, edges)

    # Get representation for each node's subtree
    representations = []
    for node in range(1, n + 1):
        if node not in tree or len(tree[node]) == 0:
            # Leaf node, representation is empty tuple
            representations.append(tuple())
        else:
            # Get representation for this node
            representations.append(get_subtree_representation(node, -1, tree))

    # Count frequency of each representation
    freq = defaultdict(int)
    for rep in representations:
        freq[rep] += 1

    # Count number of pairs with the same representation
    result = 0
    for count in freq.values():
        result += count * (count - 1) // 2

    return result

if __name__ == "__main__":
    data = sys.stdin.read().strip().split()
    if not data:
        sys.exit()

    n = int(data[0])
    edges = []
    idx = 1

    while idx < len(data):
        u = int(data[idx])
        v = int(data[idx + 1])
        edges.append((u, v))
        idx += 2

    result = count_similar_subtrees(n, edges)
    print(result)
