sofas = []
for i in range(d):
    x1, y1, x2, y2 = map(int, input().split())
    sofas.append((x1, y1, x2, y2))

cntl, cntr, cntt, cntb = map(int, input().split())

# Find which sofa matches the conditions
for i, (x1, y1, x2, y2) in enumerate(sofas):
    # Count sofas to the left (same row, x < min(x1, x2))
    left_count = 0
    for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
        if i == j:
            continue
        if yj1 == yj2 == y1 == y2:  # same row
            if min(x1, x2) > min(xj1, xj2):
                left_count += 1

    # Count sofas to the right (same row, x > max(x1, x2))
    right_count = 0
    for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
        if i == j:
            continue
        if yj1 == yj2 == y1 == y2:  # same row
            if max(x1, x2) < max(xj1, xj2):
                right_count += 1

    # Count sofas above (same column, y < min(y1, y2))
    top_count = 0
    for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
        if i == j:
            continue
        if xj1 == xj2 == x1 == x2:  # same column
            if min(y1, y2) > min(yj1, yj2):
                top_count += 1

    # Count sofas below (same column, y > max(y1, y2))
    bottom_count = 0
    for j, (xj1, yj1, xj2, yj2) in enumerate(sofas):
        if i == j:
            continue
        if xj1 == xj2 == x1 == x2:  # same column
            if max(y1, y2) < max(yj1, yj2):
                bottom_count += 1

    if left_count == cntl and right_count == cntr and top_count == cntt and bottom_count == cntb:
        print(i + 1)
        break
else:
    print(-1)
