def get_digits(n):
    return set(str(n))

def is_prime_digit(d):
    return d in {'2', '3', '5', '7'}

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    N = int(data[0])
    numbers = data[1:N+1]

    # Convert each number to its set of digits
    digit_sets = [get_digits(num) for num in numbers]

    count = 0

    # Count valid triplets
    for i in range(N):
        for j in range(i+1, N):
            for k in range(j+1, N):
                # Get intersection of the three sets
                common = digit_sets[i] & digit_sets[j] & digit_sets[k]
                if any(is_prime_digit(d) for d in common):
                    count += 1

    print(count)

if __name__ == "__main__":
    main()
"}

