def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    if not data:
        return

    N = int(data[0])
    numbers = data[1:N+1]

    # Count how many numbers contain each prime digit
    prime_digits = {'2', '3', '5', '7'}
    counts = {d: 0 for d in prime_digits}

    for num in numbers:
        digits = set(str(num))
        for d in prime_digits:
            if d in digits:
                counts[d] += 1

    # Inclusion-exclusion
    total = 0

    # Single prime digits
    for d in prime_digits:
        m = counts[d]
        total += m * (m - 1) * (m - 2) // 6

    # Two prime digits
    for d1 in prime_digits:
        for d2 in prime_digits:
            if d1 < d2:
                # Count numbers that have both d1 and d2
                count = 0
                for num in numbers:
                    digits = set(str(num))
                    if d1 in digits and d2 in digits:
                        count += 1
                total -= count * (count - 1) * (count - 2) // 6

    # Three prime digits
    for d1 in prime_digits:
        for d2 in prime_digits:
            if d1 < d2:
                for d3 in prime_digits:
                    if d3 > d2:
                        # Count numbers that have all three
                        count = 0
                        for num in numbers:
                            digits = set(str(num))
                            if d1 in digits and d2 in digits and d3 in digits:
                                count += 1
                        total += count * (count - 1) * (count - 2) // 6

    # Four prime digits
    count = 0
    for num in numbers:
        digits = set(str(num))
        if len(digits & prime_digits) == 4:
            count += 1
    total -= count * (count - 1) * (count - 2) // 6

    print(total)

if __name__ == "__main__":
