def F(t, A, B, C, D):
    return A * t * t * t + B * t * t + C * t + D

T = int(input())
for _ in range(T):
    A, B, C, D, K = map(int, input().split())

    low = 0
    high = 10**7  # Safe upper bound
    answer = 0

    while low <= high:
        mid = (low + high) // 2
        val = F(mid, A, B, C, D)

        if val <= K:
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    print(answer)
