n = int(input())
sequences = []
for _ in range(n):
    s = input().strip()
    balance = 0
    for c in s:
        if c == '(':
            balance += 1
        else:
            balance -= 1
    sequences.append((s, balance))

# dp[mask][balance] = max number of valid prefixes
# mask: which sequences we've used
# balance: current balance of brackets
# count: number of valid prefixes

dp = {}
dp[0] = {0: 0}  # mask 0, balance 0, 0 valid prefixes

for mask in dp:
    for balance, count in dp[mask].items():
        for i in range(n):
            if not (mask & (1 << i)):
                new_mask = mask | (1 << i)
                new_balance = balance + sequences[i][1]
                if new_balance >= 0:
                    # Check if this new balance is a valid prefix
                    if new_balance == 0:
                        new_count = count + 1
                    else:
                        new_count = count

                    if new_mask not in dp:
