from collections import deque

def reverse_binary(x):
    """Reverse the binary representation of x, removing leading zeros"""
    binary = bin(x)[2:]
    reversed_binary = binary[::-1]
    return int(reversed_binary, 2)

def can_reach(x, y):
    """Check if we can reach y from x using the operations"""
    if x == y:
        return True

    visited = set()
    queue = deque([x])
    visited.add(x)

    while queue:
        current = queue.popleft()

        # Add 0 to the right
        add_0 = reverse_binary((current << 1) | 0)
        if add_0 == y:
            return True
        if add_0 not in visited:
            visited.add(add_0)
            queue.append(add_0)

        # Add 1 to the right
        add_1 = reverse_binary((current << 1) | 1)
        if add_1 == y:
            return True
        if add_1 not in visited:
            visited.add(add_1)
            queue.append(add_1)

    return False

x, y = map(int, input().split())
if can_reach(x, y):
    print("YES")
else:
    print("NO")
