        adj[u].append(v)
        adj[v].append(u)

    # Check for complete subgraph of size 5
    for i in range(1, N + 1):
        if len(adj[i]) >= 4:
            friends = adj[i]
            # Check if any 4 friends form a complete subgraph
            for j in range(4):
                for k in range(j + 1, 4):
                    if friends[k] not in adj[friends[j]]:
                        break
                else:
                    # Found a complete subgraph of size 5
                    result = [i, friends[0], friends[1], friends[2], friends[3]]
                    result.sort()
                    print(' '.join(map(str, result)))
                    return

    # Check for independent set of size 5
    for i in range(1, N + 1):
        if len(adj[i]) <= 4:
            # Try to find 4 more people who are not friends with each other
            # and not friends with i
            candidates = []
            for j in range(1, N + 1):
                if j != i and j not in adj[i]:
                    candidates.append(j)

