                                    if friends[k] in adj[friends[j]]:
                                        # Found a complete subgraph of size 5
                                        result = [i, friends[j], friends[k], friends[l], friends[m]]
                                        result.sort()
                                        print(' '.join(map(str, result)))
                                        return

    # Check for independent set of size 5
    for i in range(1, N + 1):
        if len(adj[i]) <= 4:
            # Try to find 4 more people who are not friends with each other
            # and not friends with i
            candidates = []
            for j in range(1, N + 1):
                if j != i and j not in adj[i]:
                    candidates.append(j)

            if len(candidates) >= 4:
                # Check if any 4 candidates form an independent set
                for j in range(len(candidates) - 3):
                    for k in range(j + 1, len(candidates) - 2):
                        for l in range(k + 1, len(candidates) - 1):
                            for m in range(l + 1, len(candidates)):
                                # Check if these 4 candidates form an independent set
                                if candidates[m] not in adj[candidates[l]] and candidates[m] not in adj[candidates[k]] and candidates[m] not in adj[candidates[j]]:
                                    if candidates[l] not in adj[candidates[k]] and candidates[l] not in adj[candidates[j]]:
                                        if candidates[k] not in adj[candidates[j]]:
                                            # Found an independent set of size 5
                                            result = [i, candidates[j], candidates[k], candidates[l], candidates[m]]
                                            result.sort()
                                            print(' '.join(map(str, result)))
                                            return

    print(-1)

