# Track busy servers at each time
busy = set()

for _ in range(q):
    ti, ki, di = map(int, input().split())

    # Find unoccupied servers at time ti
    unoccupied = [i for i in range(1, n+1) if i not in busy]

    if len(unoccupied) >= ki:
        # Select ki smallest available servers
        selected = unoccupied[:ki]

        # Mark them as busy for di seconds
        for s in selected:
            for t in range(ti, ti + di):
                busy.add(s)

        # Output the sum of selected servers' IDs
        print(sum(selected))
    else:
        print(-1)
