def count_digit(n, d):
    """Count how many times digit d appears in all positions from 1 to n"""
    count = 0
    i = 1
    while i <= n:
        # Current position: i-th digit from right
        higher = n // (i * 10)
        current = (n // i) % 10
        lower = n % i

        # Count of digit d in this position
        if current > d:
            count += (higher + 1) * i
        elif current == d:
            count += higher * i + i
        else:
            count += higher * i

        i *= 10
    return count

def solve():
    T = int(input())
    for _ in range(T):
        N = int(input())

        # Precompute counts for each position
        pos_counts_4 = [0] * 6  # Positions 1 to 100000 have at most 6 digits
        pos_counts_7 = [0] * 6

        for i in range(1, 6):
            pos_counts_4[i] = count_digit(N, 4)
            pos_counts_7[i] = count_digit(N, 7)

        # Count valid ranges [L, R]
        ans = 0
        for L in range(1, N + 1):
            for R in range(L, N + 1):
                # Count 4s from L to R
                total_4 = 0
                for i in range(1, 6):
                    total_4 += pos_counts_4[i] - count_digit(L - 1, 4) - count_digit(R, 4) + count_digit(L - 1, 4)

                # Count 7s from L to R
                total_7 = 0
                for i in range(1, 6):
                    total_7 += pos_counts_7[i] - count_digit(L - 1, 7) - count_digit(R, 7) + count_digit(L - 1, 7)

                if total_4 == total_7:
                    ans += 1

        print(ans)

solve()
