import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    p1, p2, p3, p4, a, b = map(int, data)

    # Find the smallest number
    min_val = min(p1, p2, p3, p4)

    # Count numbers in [a, b] that are less than min_val
    if a > b:
        count = 0
    else:
        count = max(0, min_val - a)

    print(count)

if __name__ == "__main__":
    solve()
